<?php
declare(strict_types=1);
namespace App\BusinessModules\Core\Reporting\Infrastructure\Persistence;
use App\BusinessModules\Core\Reporting\Domain\Contracts\ReportSubscriptionStore; use App\BusinessModules\Core\Reporting\Domain\DTO\ReportSubscription; use App\BusinessModules\Core\Reporting\Domain\Enums\{ReportSubscriptionFrequency,ReportSubscriptionStatus}; use App\BusinessModules\Core\Reporting\Domain\ValueObjects\Sha256Hash; use App\BusinessModules\Core\Reporting\Infrastructure\Persistence\Models\ReportSubscriptionRecord; use DateTimeImmutable; use DateTimeInterface; use DateTimeZone; use Illuminate\Database\Eloquent\ModelNotFoundException;
final class EloquentReportSubscriptionStore implements ReportSubscriptionStore { public function getForActor(int $org,int $owner,string $id):ReportSubscription{return $this->dto(ReportSubscriptionRecord::query()->where(compact('id'))->where('organization_id',$org)->where('owner_id',$owner)->firstOrFail());} public function lock(string $id):ReportSubscription{return $this->dto(ReportSubscriptionRecord::query()->where('id',$id)->lockForUpdate()->firstOrFail());} public function selectDueLocked(DateTimeImmutable $now,int $limit):array{return ReportSubscriptionRecord::query()->where('status','active')->where('next_run_at','<=',$now)->orderBy('next_run_at')->orderBy('id')->lock('FOR UPDATE SKIP LOCKED')->limit($limit)->get()->map(fn($r)=>$this->dto($r))->all();} public function advanceNextRunLocked(ReportSubscription $s,DateTimeImmutable $next):void{$this->mutation($s,['next_run_at'=>$next,'transition_version'=>$s->transitionVersion+1]);} public function disableLocked(ReportSubscription $s,string $reason):void{$this->mutation($s,['status'=>'disabled','disabled_reason'=>$reason,'next_run_at'=>null,'transition_version'=>$s->transitionVersion+1]);} private function mutation(ReportSubscription $s,array $changes):void{if(ReportSubscriptionRecord::query()->where('id',$s->id)->where('transition_version',$s->transitionVersion)->update($changes)!==1)throw new \LogicException('report_subscription_concurrent_change');} private function dto(ReportSubscriptionRecord $r):ReportSubscription{$c=fn($v)=>DateTimeImmutable::createFromInterface($v);return new ReportSubscription($r->id,(int)$r->organization_id,(int)$r->owner_id,$r->saved_view_id,$r->report_code,ReportSubscriptionFrequency::from($r->frequency),$r->weekday,$r->day_of_month,$r->local_time,new DateTimeZone($r->timezone),(array)$r->period_policy_json,$r->format,ReportSubscriptionStatus::from($r->status),$r->disabled_reason,(int)$r->consecutive_failures,$r->next_run_at?$c($r->next_run_at):null,$r->execution_input_bytes,new Sha256Hash($r->execution_input_sha256),new Sha256Hash($r->definition_sha256),$r->contract_version,(int)$r->transition_version,$c($r->created_at),$c($r->updated_at));} }
